export interface Frontmatter {
  title: string;
  date?: string;
  tags?: string[];
  template?: string;
  layout?: string;
}

export interface Page {
  frontmatter: Frontmatter;
  content: string;
  slug: string;
  html?: string;
}

export interface BuildOptions {
  contentDir: string;
  outputDir: string;
  templatesDir?: string;
}

export interface ServeOptions {
  contentDir: string;
  outputDir: string;
  templatesDir?: string;
  port: number;
}

export interface Plugin {
  name: string;
  onStart?(ctx: PluginContext): void;
  beforeBuild?(ctx: PluginContext): void;
  onFile?(page: Page, ctx: PluginContext): void;
  afterBuild?(ctx: PluginContext): void;
  onEnd?(ctx: PluginContext): void;
}

export interface PluginContext extends Record<string, any> {
  options: BuildOptions;
  pages: Page[];
}

import path from 'path';
import { Plugin } from './types';

export type { Plugin };

let cachedPlugins: Plugin[] | null = null;

export function loadPlugins(): Plugin[] {
  if (cachedPlugins) return cachedPlugins;

  const configPath = path.resolve(process.cwd(), 'ssg.config');
  try {
    const mod = require(configPath);
    const config = mod.default || mod;
    if (Array.isArray(config.plugins)) {
      cachedPlugins = config.plugins;
      return cachedPlugins;
    }
  } catch {
    // config not found, use built-ins
  }

  const { builtInPlugins } = require('./plugins');
  cachedPlugins = builtInPlugins;
  return cachedPlugins;
}

export function setPlugins(plugins: Plugin[]): void {
  cachedPlugins = plugins;
}

import { marked } from 'marked';
import { Plugin } from '../types';

export const MarkdownPlugin: Plugin = {
  name: 'markdown',
  onFile(page): void {
    page.content = marked.parse(page.content, { async: false }) as string;
  },
};

import fs from 'fs';
import path from 'path';
import Handlebars from 'handlebars';
import { Plugin } from '../types';

interface TemplateEnv {
  compiledTemplates: Record<string, Handlebars.TemplateDelegate>;
  compiledLayouts: Record<string, Handlebars.TemplateDelegate>;
}

function loadPartialDir(partialsDir: string): void {
  if (!fs.existsSync(partialsDir)) return;
  const entries = fs.readdirSync(partialsDir, { withFileTypes: true });
  for (const entry of entries) {
    if (!entry.isFile() || !entry.name.endsWith('.hbs')) continue;
    const name = path.basename(entry.name, '.hbs');
    const content = fs.readFileSync(path.join(partialsDir, entry.name), 'utf-8');
    Handlebars.registerPartial(name, content);
  }
}

function createTemplateEnv(templatesDir: string): TemplateEnv {
  Handlebars.registerPartial('nav', '');

  const partialsDir = path.join(templatesDir, 'partials');
  loadPartialDir(partialsDir);

  const layoutsDir = path.join(templatesDir, 'layouts');
  const compiledTemplates: Record<string, Handlebars.TemplateDelegate> = {};
  const compiledLayouts: Record<string, Handlebars.TemplateDelegate> = {};

  if (fs.existsSync(templatesDir)) {
    const entries = fs.readdirSync(templatesDir, { withFileTypes: true });
    for (const entry of entries) {
      if (!entry.isFile() || !entry.name.endsWith('.hbs')) continue;
      const name = path.basename(entry.name, '.hbs');
      const content = fs.readFileSync(path.join(templatesDir, entry.name), 'utf-8');
      compiledTemplates[name] = Handlebars.compile(content);
    }
  }

  if (fs.existsSync(layoutsDir)) {
    const entries = fs.readdirSync(layoutsDir, { withFileTypes: true });
    for (const entry of entries) {
      if (!entry.isFile() || !entry.name.endsWith('.hbs')) continue;
      const name = path.basename(entry.name, '.hbs');
      const content = fs.readFileSync(path.join(layoutsDir, entry.name), 'utf-8');
      compiledLayouts[name] = Handlebars.compile(content);
    }
  }

  return { compiledTemplates, compiledLayouts };
}

function resolveTemplate(
  templateName: string | undefined,
  compiledTemplates: Record<string, Handlebars.TemplateDelegate>,
  defaultName: string,
): Handlebars.TemplateDelegate {
  const name = templateName || defaultName;
  const tmpl = compiledTemplates[name];
  if (!tmpl) {
    throw new Error(`Template not found: ${name}`);
  }
  return tmpl;
}

function resolveLayout(
  layoutName: string | undefined,
  compiledLayouts: Record<string, Handlebars.TemplateDelegate>,
  defaultName: string,
): Handlebars.TemplateDelegate | null {
  if (layoutName === '') return null;
  const name = layoutName || defaultName;
  if (!compiledLayouts[name]) {
    if (layoutName) {
      throw new Error(`Layout not found: ${layoutName}`);
    }
    return null;
  }
  return compiledLayouts[name];
}

function renderPage(pageHtml: string, templateName: string | undefined, layoutName: string | undefined, title: string, date: string | undefined, tags: string[] | undefined, tagsList: string, slug: string, env: TemplateEnv): string {
  const template = resolveTemplate(templateName, env.compiledTemplates, 'page');
  const layout = resolveLayout(layoutName, env.compiledLayouts, 'default');

  const context = {
    title,
    date: date || null,
    tags: tags || [],
    tagsList,
    content: pageHtml,
    slug,
  };

  const renderedContent = template(context);

  if (!layout) {
    return renderedContent;
  }

  return layout({
    title,
    body: renderedContent,
  });
}

function renderIndex(pages: Array<{ title: string; slug: string; date: string | null }>, env: TemplateEnv): string {
  const template = resolveTemplate(undefined, env.compiledTemplates, 'index');
  const layout = resolveLayout(undefined, env.compiledLayouts, 'default');

  const context = {
    title: 'My Site',
    pages,
  };

  const renderedContent = template(context);

  if (!layout) {
    return renderedContent;
  }

  return layout({
    title: 'My Site',
    body: renderedContent,
  });
}

export const TemplatePlugin: Plugin = {
  name: 'template',

  beforeBuild(ctx): void {
    const templatesDir = path.resolve(ctx.options.templatesDir || './templates');

    if (!fs.existsSync(templatesDir)) {
      throw new Error(`Templates directory not found: ${templatesDir}`);
    }

    const env = createTemplateEnv(templatesDir);
    ctx._templateEnv = env;

    ctx._renderIndex = function (pagesList: Array<{ title: string; slug: string; date: string | null }>): string {
      return renderIndex(pagesList, env);
    };

    ctx._renderPage = function (
      pageHtml: string,
      templateName: string | undefined,
      layoutName: string | undefined,
      title: string,
      date: string | undefined,
      tags: string[] | undefined,
      tagsList: string,
      slug: string,
    ): string {
      return renderPage(pageHtml, templateName, layoutName, title, date, tags, tagsList, slug, env);
    };
  },

  onFile(page, ctx): void {
    const templateName = page.frontmatter.template;
    const layoutName = page.frontmatter.layout;

    const tagsList = page.frontmatter.tags && page.frontmatter.tags.length > 0
      ? page.frontmatter.tags.join(', ')
      : '';

    page.html = ctx._renderPage(
      page.content,
      templateName,
      layoutName,
      page.frontmatter.title,
      page.frontmatter.date,
      page.frontmatter.tags,
      tagsList,
      page.slug,
    );
  },
};

import http from 'http';
import fs from 'fs';
import path from 'path';
import { WebSocketServer, WebSocket } from 'ws';
import chokidar from 'chokidar';
import { Plugin, ServeOptions } from '../types';
import { build } from '../build';

function getMimeType(filePath: string): string {
  const ext = path.extname(filePath).toLowerCase();
  const mimeTypes: Record<string, string> = {
    '.html': 'text/html',
    '.htm': 'text/html',
    '.css': 'text/css',
    '.js': 'application/javascript',
    '.json': 'application/json',
    '.png': 'image/png',
    '.jpg': 'image/jpeg',
    '.jpeg': 'image/jpeg',
    '.gif': 'image/gif',
    '.svg': 'image/svg+xml',
    '.ico': 'image/x-icon',
  };
  return mimeTypes[ext] || 'application/octet-stream';
}

function injectReloadScript(html: string, port: number): string {
  const script = `<script>(function(){var s=new WebSocket('ws://localhost:${port}/__livereload');s.onmessage=function(m){if(m.data==='reload')window.location.reload()};})();</script>`;
  if (html.includes('</body>')) {
    return html.replace('</body>', script + '</body>');
  }
  return html + script;
}

export const DevServerPlugin: Plugin = {
  name: 'dev-server',
};

export function createDevServer(options: ServeOptions): http.Server {
  const { contentDir, outputDir, templatesDir, port } = options;
  const resolvedOutputDir = path.resolve(outputDir);
  const resolvedTemplatesDir = path.resolve(templatesDir || './templates');

  build({ contentDir, outputDir, templatesDir });

  const server = http.createServer((req, res) => {
    const url = req.url || '/';
    const reqPath = url === '/' ? 'index.html' : url;
    const relativePath = reqPath.startsWith('/') ? reqPath.slice(1) : reqPath;
    const filePath = path.join(resolvedOutputDir, relativePath);

    const resolved = path.resolve(filePath);
    if (!resolved.startsWith(resolvedOutputDir + path.sep) && resolved !== resolvedOutputDir) {
      res.writeHead(403);
      res.end('Forbidden');
      return;
    }

    if (!fs.existsSync(resolved) || !fs.statSync(resolved).isFile()) {
      res.writeHead(404);
      res.end('Not Found');
      return;
    }

    const mimeType = getMimeType(resolved);

    if (mimeType === 'text/html') {
      let html = fs.readFileSync(resolved, 'utf-8');
      html = injectReloadScript(html, port);
      res.writeHead(200, { 'Content-Type': mimeType });
      res.end(html);
    } else {
      const content = fs.readFileSync(resolved);
      res.writeHead(200, { 'Content-Type': mimeType });
      res.end(content);
    }
  });

  const wss = new WebSocketServer({ noServer: true });

  server.on('upgrade', (request, socket, head) => {
    const { pathname } = new URL(request.url || '', `http://localhost:${port}`);
    if (pathname === '/__livereload') {
      wss.handleUpgrade(request, socket, head, (ws) => {
        wss.emit('connection', ws, request);
      });
    } else {
      socket.destroy();
    }
  });

  const clients = new Set<WebSocket>();

  wss.on('connection', (ws) => {
    clients.add(ws);
    ws.on('close', () => {
      clients.delete(ws);
    });
  });

  const watchPaths = [
    path.resolve(contentDir),
    resolvedTemplatesDir,
  ];

  let rebuildTimeout: ReturnType<typeof setTimeout> | null = null;

  const watcher = chokidar.watch(watchPaths, {
    ignoreInitial: true,
    awaitWriteFinish: {
      stabilityThreshold: 200,
      pollInterval: 100,
    },
  });

  watcher.on('all', (event, filePath) => {
    console.log(`[change] ${event}: ${filePath}`);
    if (rebuildTimeout) clearTimeout(rebuildTimeout);
    rebuildTimeout = setTimeout(() => {
      try {
        build({ contentDir, outputDir, templatesDir });
        console.log('[rebuilt]');
        for (const client of clients) {
          if (client.readyState === WebSocket.OPEN) {
            client.send('reload');
          }
        }
      } catch (err) {
        console.error('[build error]', (err as Error).message);
      }
    }, 150);
  });

  server.on('close', () => {
    watcher.close();
    wss.close();
  });

  server.listen(port, () => {
    console.log(`Dev server running at http://localhost:${port}/`);
  });

  return server;
}

import { Plugin } from '../types';
import { MarkdownPlugin } from './markdown';
import { TemplatePlugin } from './template';
import { DevServerPlugin } from './devserver';

export const builtInPlugins: Plugin[] = [
  MarkdownPlugin,
  TemplatePlugin,
  DevServerPlugin,
];

export { MarkdownPlugin } from './markdown';
export { TemplatePlugin } from './template';
export { DevServerPlugin } from './devserver';

